() => {
  test('tokenizes basic function', () => {
    const source = 'func add(a: number, b: number) -> number';
    const lexer = new Lexer(source);
    const tokens = lexer.tokenize();

    expect(tokens[0].type).toBe(TokenType.FUNC);
    expect(tokens[1].type).toBe(TokenType.IDENTIFIER);
    expect(tokens[1].value).toBe('add');
    expect(tokens[2].type).toBe(TokenType.LPAREN);
  });

  test('tokenizes annotations', () => {
    const source = '@confidence(0.90)';
    const lexer = new Lexer(source);
    const tokens = lexer.tokenize();

    expect(tokens[0].type).toBe(TokenType.AT);
    expect(tokens[0].value).toContain('@confidence');
  });

  test('tokenizes strings', () => {
    const source = '"hello world"';
    const lexer = new Lexer(source);
    const tokens = lexer.tokenize();

    expect(tokens[0].type).toBe(TokenType.STRING);
    expect(tokens[0].value).toBe('hello world');
  });

  test('tokenizes numbers', () => {
    const source = '123.45';
    const lexer = new Lexer(source);
    const tokens = lexer.tokenize();

    expect(tokens[0].type).toBe(TokenType.NUMBER);
    expect(tokens[0].value).toBe('123.45');
  });

  test('skips comments', () => {
    const source = '// comment\nfunc test()';
    const lexer = new Lexer(source);
    const tokens = lexer.tokenize();

    // Should not include comment tokens
    expect(tokens[0].type).toBe(TokenType.FUNC);
  });
}

() => {
  test('parses simple function', () => {
    const source = 'func add(a: number, b: number) -> number { return a + b }';
    const parser = new Parser();
    const ast = parser.parse(source);

    expect(ast).toBeDefined();
    expect(ast.length).toBeGreaterThan(0);
    expect(ast[0].type).toBe('FunctionDeclaration');
  });

  test('parses function with annotations', () => {
    const source = '@confidence(0.90)\nfunc test() { return true }';
    const parser = new Parser();
    const ast = parser.parse(source);

    expect(ast).toBeDefined();
    expect(ast[0].type).toBe('FunctionDeclaration');
  });

  test('parses if statement', () => {
    const source = 'func test(x: number) { if x == 0 { return true } }';
    const parser = new Parser();
    const ast = parser.parse(source);

    expect(ast).toBeDefined();
    const func = ast[0] as any;
    expect(func.body.body[0].type).toBe('IfStatement');
  });

  test('parses variable declaration', () => {
    const source = 'func test() { x = 10 }';
    const parser = new Parser();
    const ast = parser.parse(source);

    expect(ast).toBeDefined();
    const func = ast[0] as any;
    expect(func.body.body[0].type).toBe('VariableDeclaration');
  });

  test('parses return statement', () => {
    const source = 'func test() { return 42 }';
    const parser = new Parser();
    const ast = parser.parse(source);

    expect(ast).toBeDefined();
    const func = ast[0] as any;
    expect(func.body.body[0].type).toBe('ReturnStatement');
  });
}

() => {
  test('transpiles simple function', async () => {
    const source = `
@confidence(0.95)
func add(a: number, b: number) -> number {
    return a + b
}
`;

    const result = await transpile(source);

    expect(result.code).toContain('function add');
    expect(result.code).toContain('a: number');
    expect(result.code).toContain('b: number');
    expect(result.code).toContain('return a + b');
  });

  test('includes runtime imports', async () => {
    const source = 'func test() { return true }';
    const result = await transpile(source);

    expect(result.code).toContain('import');
    expect(result.code).toContain('AgenticRuntime');
    expect(result.code).toContain('Result');
  });

  test('generates property tests when requested', async () => {
    const source = `
@property("never returns null")
func greet(name: string) -> string {
    return "Hello"
}
`;

    const result = await transpile(source, { propertyTests: true });

    expect(result.propertyTests).toBeDefined();
    expect(result.propertyTests).toContain('test.prop');
    expect(result.propertyTests).toContain('fc.string()');
  });

  test('preserves annotations as comments', async () => {
    const source = `
@confidence(0.90)
@needs(database: Database)
func test() {
    return true
}
`;

    const result = await transpile(source);

    expect(result.code).toContain('// @confidence');
    expect(result.code).toContain('// @needs');
  });

  test('generates source map when requested', async () => {
    const source = 'func test() { return true }';
    const result = await transpile(source, { sourceMap: true });

    expect(result.sourceMap).toBeDefined();
    const map = JSON.parse(result.sourceMap!);
    expect(map.version).toBe(3);
    expect(map.sources).toBeDefined();
  });
}

