function compileFile(inputPath: string, options: any) {
  // Read source file
  const source = fs.readFileSync(inputPath, 'utf-8');

  // Parse
  const parser = new Parser();
  const ast = parser.parse(source);

  // Generate TypeScript
  const generator = new TypeScriptGenerator(inputPath);
  const code = generator.generate(ast);

  // Determine output path
  const outputPath = options.output || inputPath.replace('.agentic', '.ts');

  // Write output
  fs.writeFileSync(outputPath, code, 'utf-8');

  // Write source map if requested
  if (options.sourceMap) {
    const sourceMapPath = outputPath + '.map';
    fs.writeFileSync(sourceMapPath, generator.getSourceMap(), 'utf-8');
  }

  return {
    outputPath,
    diagnostics: [] as any[],
  };
}

async function transpile(
  source: string,
  options: { sourceMap?: boolean; propertyTests?: boolean } = {}
): Promise<{
  code: string;
  sourceMap?: string;
  propertyTests?: string;
}> {
  const parser = new ParserClass();
  const ast = parser.parse(source);

  const generator = new TSGenerator('input.agentic');
  const code = generator.generate(ast);

  const result: { code: string; sourceMap?: string; propertyTests?: string } = { code };

  if (options.sourceMap) {
    result.sourceMap = generator.getSourceMap();
  }

  if (options.propertyTests) {
    const testGen = new PropTestGen();
    const tests = testGen.generate(ast);
    result.propertyTests = tests.map((t: any) => t.testCode).join('\n\n');
  }

  return result;
}

/**
 * Core type definitions for the Agentic language
 */

export interface SourceLocation {
  line: number;
  column: number;
  offset: number;
}

export interface SourceRange {
  start: SourceLocation;
  end: SourceLocation;
}

// AST Node Types
export type ASTNode =
  | FunctionDeclaration
  | VariableDeclaration
  | IfStatement
  | ReturnStatement
  | BinaryExpression
  | CallExpression
  | Identifier
  | Literal
  | BlockStatement
  | MatchExpression
  | ErrorRecovery;

export interface BaseNode {
  type: string;
  loc?: SourceRange;
}

export interface FunctionDeclaration extends BaseNode {
  type: 'FunctionDeclaration';
  name: string;
  params: Parameter[];
  returnType: TypeAnnotation | null;
  body: BlockStatement;
  annotations: Annotation[];
}

export interface Parameter {
  name: string;
  typeAnnotation: TypeAnnotation | null;
}

export interface TypeAnnotation {
  kind: 'primitive' | 'union' | 'result' | 'custom';

  value: string | TypeAnnotation[];
}

export interface Annotation {
  name: string;
  args: Record<string, any>;
  loc?: SourceRange;
}

export interface VariableDeclaration extends BaseNode {
  type: 'VariableDeclaration';
  name: string;
  initializer: ASTNode | null;
  typeAnnotation: TypeAnnotation | null;
}

export interface IfStatement extends BaseNode {
  type: 'IfStatement';
  condition: ASTNode;
  consequent: BlockStatement;
  alternate: BlockStatement | IfStatement | null;
}

export interface ReturnStatement extends BaseNode {
  type: 'ReturnStatement';
  argument: ASTNode | null;
}

export interface BinaryExpression extends BaseNode {
  type: 'BinaryExpression';
  operator: string;
  left: ASTNode;
  right: ASTNode;
}

export interface CallExpression extends BaseNode {
  type: 'CallExpression';
  callee: ASTNode;
  arguments: ASTNode[];
}

export interface Identifier extends BaseNode {
  type: 'Identifier';
  name: string;
}

export interface Literal extends BaseNode {
  type: 'Literal';
  value: string | number | boolean | null;
  raw: string;

}

export interface BlockStatement extends BaseNode {
  type: 'BlockStatement';
  body: ASTNode[];
}

export interface MatchExpression extends BaseNode {
  type: 'MatchExpression';
  discriminant: ASTNode;
  cases: MatchCase[];
}

export interface MatchCase {
  pattern: string; // "Ok" | "Err" | "_"
  binding?: string; // Variable name
  body: ASTNode;
}

export interface ErrorRecovery extends BaseNode {
  type: 'ErrorRecovery';
  binding: string;
  contextBlock: ContextBlock;
  errorAction: ASTNode;
}

export interface ContextBlock {
  what_failed?: string;
  what_i_tried?: string;
  current_state?: Record<string, any>;
  likely_cause?: string;
  suggestions?: string[];
  recovery?: {
    action: string;
    command?: string;
  };
}

// Transpiler configuration
export interface TranspilerOptions {
  sourceMap?: boolean;
  target?: 'ES2020' | 'ES2015' | 'ESNext';
  includeRuntime?: boolean;
  outputPath?: string;
}

// Compilation result
export interface CompilationResult {
  code: string;
  sourceMap?: string;

  diagnostics: Diagnostic[];
  propertyTests?: PropertyTest[];
}

export interface Diagnostic {
  severity: 'error' | 'warning' | 'info';
  message: string;
  location: SourceRange;
  suggestion?: string;
}

export interface PropertyTest {
  name: string;
  description: string;
  testCode: string;
}

function Ok<T>(value: T): Result<T, never> {
  return { ok: true, value };
}

function Err<E>(error: E): Result<never, E> {
  return { ok: false, error };
}

class ConfidenceTracker {
  private confidenceMap = new Map<string, ConfidenceMetadata>();

  register(identifier: string, confidence: number, reason?: string) {
    this.confidenceMap.set(identifier, {
      level: confidence,
      reason,
      timestamp: Date.now(),
    });

    if (confidence < 0.80) {
      console.warn(
        `⚠️  Low confidence (${confidence.toFixed(2)}) in ${identifier}: ${reason || 'No reason provided'}`
      );
    }
  }

  get(identifier: string): ConfidenceMetadata | undefined {
    return this.confidenceMap.get(identifier);
  }

  all(): Record<string, ConfidenceMetadata> {
    return Object.fromEntries(this.confidenceMap);
  }
}

class ContextValidator {
  validate(requirements: ContextRequirement[], context: Record<string, any>): void {
    const missing: string[] = [];

    for (const req of requirements) {
      if (req.required && !(req.name in context)) {
        missing.push(req.name);
      }
    }

    if (missing.length > 0) {
      throw new Error(
        `Missing required context: ${missing.join(', ')}\n` +
        `Required: ${requirements.map(r => r.name).join(', ')}\n` +
        `Available: ${Object.keys(context).join(', ')}`
      );
    }
  }
}

class HealthCheckMonitor {
  private checks = new Map<string, HealthCheck>();
  private timers = new Map<string, NodeJS.Timeout>();

  register(check: HealthCheck) {
    this.checks.set(check.name, check);

    if (check.interval) {
      const timer = setInterval(async () => {
        await this.runCheck(check.name);
      }, check.interval);

      this.timers.set(check.name, timer);
    }
  }

  async runCheck(name: string): Promise<HealthStatus> {
    const check = this.checks.get(name);
    if (!check) {
      throw new Error(`Health check not found: ${name}`);
    }

    const status = await check.check();

    if (status === 'FAILED' && check.recovery) {
      console.warn(`Health check ${name} failed - attempting recovery`);
      try {
        await check.recovery();
        console.info(`Recovery successful for ${name}`);
      } catch (error) {
        console.error(`Recovery failed for ${name}:`, error);
      }
    }

    return status;
  }

  stopAll() {
    for (const timer of this.timers.values()) {
      clearInterval(timer);
    }
    this.timers.clear();
  }
}

class AgenticRuntime {
  static confidence = new ConfidenceTracker();
  static context = new ContextValidator();
  static health = new HealthCheckMonitor();

  // Decorator-like function for confidence tracking
  static withConfidence<T extends (...args: any[]) => any>(
    fn: T,
    confidence: number,
    reason?: string
  ): T {
    this.confidence.register(fn.name, confidence, reason);
    return fn;
  }

  // Decorator-like function for context validation
  static withContext<T extends (...args: any[]) => any>(
    fn: T,
    requirements: ContextRequirement[]
  ): T {
    return ((...args: any[]) => {
      const context = args[args.length - 1]; // Assume last arg is context
      this.context.validate(requirements, context);
      return fn(...args);
    }) as T;
  }

  // Helper for error recovery
  static async tryWithRecovery<T>(
    operation: () => Promise<T>,
    recovery: () => Promise<T>,
    maxAttempts = 3
  ): Promise<T> {
    let lastError: Error | null = null;

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      try {
        return await operation();
      } catch (error) {
        lastError = error as Error;
        console.warn(`Attempt ${attempt}/${maxAttempts} failed:`, error);

        if (attempt < maxAttempts) {
          console.info('Attempting recovery...');
          try {
            return await recovery();
          } catch (recoveryError) {
            console.warn('Recovery failed:', recoveryError);
          }
        }
      }
    }

    throw lastError;
  }
}

class PropertyTestGenerator {
  generate(ast: AST.ASTNode[]): PropertyTest[] {
    const tests: PropertyTest[] = [];

    for (const node of ast) {
      if (node.type === 'FunctionDeclaration') {
        const funcTests = this.generateForFunction(node);
        if (funcTests) {
          tests.push(funcTests);
        }
      }
    }

    return tests;
  }

  private generateForFunction(func: AST.FunctionDeclaration): PropertyTest | null {
    const properties = this.inferProperties(func);

    if (properties.length === 0) {
      return null;
    }

    const testCode = this.generateTestCode(func, properties);

    return {
      functionName: func.name,
      properties,
      testCode,
    };
  }

  private inferProperties(func: AST.FunctionDeclaration): Property[] {
    const properties: Property[] = [];

    // Extract properties from annotations
    for (const annotation of func.annotations) {
      if (annotation.name === 'property') {
        properties.push({
          name: annotation.args.name || 'custom_property',
          description: annotation.args.description || '',
          testFunction: '',
        });
      }
    }

    // Infer properties from return type
    if (func.returnType) {
      properties.push(...this.inferFromReturnType(func.returnType));
    }

    // Infer properties from parameters
    properties.push(...this.inferFromParameters(func.params));

    return properties;
  }

  private inferFromReturnType(returnType: AST.TypeAnnotation): Property[] {
    const properties: Property[] = [];

    // Result<T, E> should handle both success and failure
    if (returnType.kind === 'result') {
      properties.push({
        name: 'handles_success_case',
        description: 'Function handles successful result',
        testFunction: 'result.ok === true',
      });

      properties.push({
        name: 'handles_error_case',
        description: 'Function handles error result',
        testFunction: 'result.ok === false || result.ok === true',
      });
    }

    // Never returns null/undefined
    if (returnType.kind === 'primitive' || returnType.kind === 'custom') {
      properties.push({
        name: 'never_returns_null',
        description: 'Function never returns null or undefined',
        testFunction: 'result !== null && result !== undefined',
      });
    }

    return properties;
  }

  private inferFromParameters(params: AST.Parameter[]): Property[] {
    const properties: Property[] = [];

    // If function takes a string, test with empty string
    if (params.some(p => p.typeAnnotation?.value === 'string')) {
      properties.push({
        name: 'handles_empty_string',
        description: 'Function handles empty string input',
        testFunction: 'typeof result !== "undefined"',
      });
    }

    // If function takes a number, test with zero and negative
    if (params.some(p => p.typeAnnotation?.value === 'number')) {
      properties.push({
        name: 'handles_zero',
        description: 'Function handles zero input',
        testFunction: 'typeof result !== "undefined"',
      });

      properties.push({
        name: 'handles_negative',
        description: 'Function handles negative numbers',
        testFunction: 'typeof result !== "undefined"',
      });
    }

    return properties;
  }

  private generateTestCode(func: AST.FunctionDeclaration, properties: Property[]): string {
    const imports = `import { test } from '@fast-check/vitest';
import * as fc from 'fast-check';
import { ${func.name} } from './${func.name}';

`;

    let testCode = imports;

    // Generate arbitraries for parameters
    const arbitraries = func.params.map(p => this.generateArbitrary(p));

    // Generate test cases
    for (const property of properties) {
      testCode += `test.prop([${arbitraries.join(', ')}], (${func.params.map(p => p.name).join(', ')}) => {
  const result = ${func.name}(${func.params.map(p => p.name).join(', ')});
  expect(${property.testFunction}).toBe(true);
}, { numRuns: 1000 });\n\n`;
    }

    return testCode;
  }

  private generateArbitrary(param: AST.Parameter): string {
    if (!param.typeAnnotation) {
      return 'fc.anything()';
    }

    const type = param.typeAnnotation.value;

    switch (type) {
      case 'string':
        return 'fc.string()';
      case 'number':
        return 'fc.integer()';
      case 'boolean':
        return 'fc.boolean()';
      default:
        return 'fc.anything()';
    }
  }
}

class Lexer {
  private source: string;
  private pos = 0;
  private line = 1;
  private column = 1;
  private tokens: Token[] = [];

  constructor(source: string) {
    this.source = source;
  }

  tokenize(): Token[] {
    this.tokens = [];

    while (this.pos < this.source.length) {
      this.skipWhitespace();

      if (this.pos >= this.source.length) break;

      // Skip comments
      if (this.peek() === '/' && this.peek(1) === '/') {
        this.skipLineComment();
        continue;
      }

      if (this.peek() === '/' && this.peek(1) === '*') {
        this.skipBlockComment();
        continue;
      }

      const token = this.nextToken();
      if (token.type !== TokenType.NEWLINE) {
        this.tokens.push(token);
      }
    }

    this.tokens.push(this.createToken(TokenType.EOF, ''));
    return this.tokens;
  }

  private nextToken(): Token {
    const char = this.peek();

    // Annotations
    if (char === '@') {
      return this.scanAnnotation();
    }

    // Strings
    if (char === '"' || char === "'") {
      return this.scanString();
    }

    // Numbers
    if (this.isDigit(char)) {
      return this.scanNumber();
    }

    // Identifiers and keywords
    if (this.isAlpha(char) || char === '_') {
      return this.scanIdentifier();
    }

    // Operators and delimiters
    return this.scanOperator();
  }

  private scanAnnotation(): Token {
    const start = this.pos;
    this.advance(); // consume @

    if (this.isAlpha(this.peek())) {
      while (this.isAlphaNumeric(this.peek())) {
        this.advance();
      }
    }

    const value = this.source.substring(start, this.pos);
    return this.createToken(TokenType.AT, value);
  }

  private scanString(): Token {
    const quote = this.peek();
    this.advance(); // consume opening quote

    const start = this.pos;
    while (this.peek() !== quote && !this.isAtEnd()) {
      if (this.peek() === '\\') {
        this.advance(); // skip escape
      }
      this.advance();
    }

    const value = this.source.substring(start, this.pos);
    this.advance(); // consume closing quote

    return this.createToken(TokenType.STRING, value);
  }

  private scanNumber(): Token {
    const start = this.pos;

    while (this.isDigit(this.peek())) {
      this.advance();
    }

    if (this.peek() === '.' && this.isDigit(this.peek(1))) {
      this.advance(); // consume .
      while (this.isDigit(this.peek())) {
        this.advance();
      }
    }

    const value = this.source.substring(start, this.pos);
    return this.createToken(TokenType.NUMBER, value);
  }

  private scanIdentifier(): Token {
    const start = this.pos;

    while (this.isAlphaNumeric(this.peek())) {
      this.advance();
    }

    const value = this.source.substring(start, this.pos);
    const type = KEYWORDS[value] || TokenType.IDENTIFIER;

    return this.createToken(type, value);
  }

  private scanOperator(): Token {
    const char = this.peek();
    const next = this.peek(1);

    // Two-character operators
    if (char === '-' && next === '>') {
      this.advance();
      this.advance();
      return this.createToken(TokenType.ARROW, '->');
    }

    if (char === '=' && next === '>') {
      this.advance();
      this.advance();
      return this.createToken(TokenType.FAT_ARROW, '=>');
    }

    if (char === '=' && next === '=') {
      this.advance();
      this.advance();
      return this.createToken(TokenType.EQ, '==');
    }

    if (char === '!' && next === '=') {
      this.advance();
      this.advance();
      return this.createToken(TokenType.NEQ, '!=');
    }

    if (char === '<' && next === '=') {
      this.advance();
      this.advance();
      return this.createToken(TokenType.LTE, '<=');
    }

    if (char === '>' && next === '=') {
      this.advance();
      this.advance();
      return this.createToken(TokenType.GTE, '>=');
    }

    // Single-character operators
    const singleChars: Record<string, TokenType> = {
      '(': TokenType.LPAREN,
      ')': TokenType.RPAREN,
      '{': TokenType.LBRACE,
      '}': TokenType.RBRACE,
      '[': TokenType.LBRACKET,
      ']': TokenType.RBRACKET,
      ',': TokenType.COMMA,
      '.': TokenType.DOT,
      ':': TokenType.COLON,
      ';': TokenType.SEMICOLON,
      '|': TokenType.PIPE,
      '<': TokenType.LT,
      '>': TokenType.GT,
      '\n': TokenType.NEWLINE,
    };

    const type = singleChars[char];
    if (type) {
      this.advance();
      return this.createToken(type, char);
    }

    // Unknown
    this.advance();
    return this.createToken(TokenType.UNKNOWN, char);
  }

  private skipWhitespace() {
    while (!this.isAtEnd() && /\s/.test(this.peek()) && this.peek() !== '\n') {
      this.advance();
    }
  }

  private skipLineComment() {
    while (this.peek() !== '\n' && !this.isAtEnd()) {
      this.advance();
    }
  }

  private skipBlockComment() {
    this.advance(); // /
    this.advance(); // *

    while (!this.isAtEnd()) {
      if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance();
        this.advance();
        break;
      }
      this.advance();
    }
  }

  private peek(offset = 0): string {
    const index = this.pos + offset;
    return index < this.source.length ? this.source[index] : '\0';
  }

  private advance(): string {
    const char = this.source[this.pos++];
    if (char === '\n') {
      this.line++;
      this.column = 1;
    } else {
      this.column++;
    }
    return char;
  }

  private isAtEnd(): boolean {
    return this.pos >= this.source.length;
  }

  private isDigit(char: string): boolean {
    return /[0-9]/.test(char);
  }

  private isAlpha(char: string): boolean {
    return /[a-zA-Z_]/.test(char);
  }

  private isAlphaNumeric(char: string): boolean {
    return this.isAlpha(char) || this.isDigit(char);
  }

  private createToken(type: TokenType, value: string): Token {
    return {
      type,
      value,
      line: this.line,
      column: this.column - value.length,
      offset: this.pos - value.length,
    };
  }
}

class Parser {
  private tokens: Token[] = [];
  private current = 0;

  parse(source: string): AST.ASTNode[] {
    const lexer = new Lexer(source);
    this.tokens = lexer.tokenize();
    this.current = 0;

    const statements: AST.ASTNode[] = [];

    while (!this.isAtEnd()) {
      const stmt = this.parseStatement();
      if (stmt) {
        statements.push(stmt);
      }
    }

    return statements;
  }

  private parseStatement(): AST.ASTNode | null {
    // Collect annotations (they're metadata for next statement)
    const annotations: AST.Annotation[] = [];
    while (this.check(TokenType.AT)) {
      annotations.push(this.parseAnnotation());
    }

    if (this.check(TokenType.FUNC)) {
      const func = this.parseFunctionDeclaration();
      func.annotations = annotations;
      return func;
    }

    if (this.check(TokenType.RETURN)) {
      return this.parseReturnStatement();
    }

    if (this.check(TokenType.IF)) {
      return this.parseIfStatement();
    }

    // Variable declaration or assignment
    if (this.check(TokenType.IDENTIFIER)) {
      return this.parseVariableOrExpression();
    }

    return null;
  }

  private parseFunctionDeclaration(): AST.FunctionDeclaration {
    this.consume(TokenType.FUNC);

    const nameToken = this.consume(TokenType.IDENTIFIER);
    const name = nameToken.value;

    this.consume(TokenType.LPAREN);
    const params = this.parseParameterList();
    this.consume(TokenType.RPAREN);

    let returnType: AST.TypeAnnotation | null = null;
    if (this.match(TokenType.ARROW)) {
      returnType = this.parseTypeAnnotation();
    }

    const body = this.parseBlockStatement();

    return {
      type: 'FunctionDeclaration',
      name,
      params,
      returnType,
      body,
      annotations: [],
    };
  }

  private parseParameterList(): AST.Parameter[] {
    const params: AST.Parameter[] = [];

    if (this.check(TokenType.RPAREN)) {
      return params;
    }

    do {
      const nameToken = this.consume(TokenType.IDENTIFIER);
      let typeAnnotation: AST.TypeAnnotation | null = null;

      if (this.match(TokenType.COLON)) {
        typeAnnotation = this.parseTypeAnnotation();
      }

      params.push({
        name: nameToken.value,
        typeAnnotation,
      });
    } while (this.match(TokenType.COMMA));

    return params;
  }

  private parseTypeAnnotation(): AST.TypeAnnotation {
    // Simple type parsing: string | number | Result<T, E> | custom
    const token = this.consume(TokenType.IDENTIFIER);

    // Check for Result<T, E>
    if (token.value === 'Result' && this.match(TokenType.LT)) {
      const okType = this.parseTypeAnnotation();
      this.consume(TokenType.COMMA);
      const errType = this.parseTypeAnnotation();
      this.consume(TokenType.GT);

      return {
        kind: 'result',
        value: [okType, errType],
      };
    }

    // Check for union types: Type1 | Type2
    if (this.check(TokenType.PIPE)) {
      const types: AST.TypeAnnotation[] = [{ kind: 'custom', value: token.value }];

      while (this.match(TokenType.PIPE)) {
        const nextToken = this.consume(TokenType.IDENTIFIER);
        types.push({ kind: 'custom', value: nextToken.value });
      }

      return {
        kind: 'union',
        value: types,
      };
    }

    // Primitive or custom type
    const primitives = ['string', 'number', 'boolean', 'void'];
    const kind = primitives.includes(token.value) ? 'primitive' : 'custom';

    return {
      kind,
      value: token.value,
    };
  }

  private parseBlockStatement(): AST.BlockStatement {
    this.consume(TokenType.LBRACE);

    const body: AST.ASTNode[] = [];

    while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
      const stmt = this.parseStatement();
      if (stmt) {
        body.push(stmt);
      }
    }

    this.consume(TokenType.RBRACE);

    return {
      type: 'BlockStatement',
      body,
    };
  }

  private parseReturnStatement(): AST.ReturnStatement {
    this.consume(TokenType.RETURN);

    let argument: AST.ASTNode | null = null;

    if (!this.check(TokenType.SEMICOLON) && !this.check(TokenType.RBRACE)) {
      argument = this.parseExpression();
    }

    return {
      type: 'ReturnStatement',
      argument,
    };
  }

  private parseIfStatement(): AST.IfStatement {
    this.consume(TokenType.IF);

    const condition = this.parseExpression();
    const consequent = this.parseBlockStatement();

    let alternate: AST.BlockStatement | AST.IfStatement | null = null;

    if (this.match(TokenType.ELSE)) {
      if (this.check(TokenType.IF)) {
        alternate = this.parseIfStatement();
      } else {
        alternate = this.parseBlockStatement();
      }
    }

    return {
      type: 'IfStatement',
      condition,
      consequent,
      alternate,
    };
  }

  private parseVariableOrExpression(): AST.ASTNode {
    const nameToken = this.peek();

    // Look ahead for assignment
    if (this.peekNext()?.type === TokenType.EQ || this.peekNext()?.value === '=') {
      this.advance(); // consume identifier
      this.advance(); // consume =

      const initializer = this.parseExpression();

      return {
        type: 'VariableDeclaration',
        name: nameToken.value,
        initializer,
        typeAnnotation: null,
      };
    }

    return this.parseExpression();
  }

  private parseExpression(): AST.ASTNode {
    return this.parseBinaryExpression();
  }

  private parseBinaryExpression(): AST.ASTNode {
    let left = this.parsePrimaryExpression();

    const operators = [TokenType.EQ, TokenType.NEQ, TokenType.LT, TokenType.GT, TokenType.LTE, TokenType.GTE];

    while (operators.some(op => this.check(op))) {
      const operator = this.advance().value;
      const right = this.parsePrimaryExpression();

      left = {
        type: 'BinaryExpression',
        operator,
        left,
        right,
      };
    }

    return left;
  }

  private parsePrimaryExpression(): AST.ASTNode {
    // Literals
    if (this.check(TokenType.NUMBER)) {
      const token = this.advance();
      return {
        type: 'Literal',
        value: parseFloat(token.value),
        raw: token.value,
      };
    }

    if (this.check(TokenType.STRING)) {
      const token = this.advance();
      return {
        type: 'Literal',
        value: token.value,
        raw: `"${token.value}"`,
      };
    }

    if (this.check(TokenType.BOOLEAN)) {
      const token = this.advance();
      return {
        type: 'Literal',
        value: token.value === 'true',
        raw: token.value,
      };
    }

    if (this.check(TokenType.NULL)) {
      const token = this.advance();
      return {
        type: 'Literal',
        value: null,
        raw: 'null',
      };
    }

    // Function calls
    if (this.check(TokenType.IDENTIFIER)) {
      const nameToken = this.advance();

      if (this.match(TokenType.LPAREN)) {
        const args: AST.ASTNode[] = [];

        if (!this.check(TokenType.RPAREN)) {
          do {
            args.push(this.parseExpression());
          } while (this.match(TokenType.COMMA));
        }

        this.consume(TokenType.RPAREN);

        return {
          type: 'CallExpression',
          callee: { type: 'Identifier', name: nameToken.value },
          arguments: args,
        };
      }

      // Method calls (dot notation)
      if (this.match(TokenType.DOT)) {
        const methodToken = this.consume(TokenType.IDENTIFIER);
        this.consume(TokenType.LPAREN);

        const args: AST.ASTNode[] = [];
        if (!this.check(TokenType.RPAREN)) {
          do {
            args.push(this.parseExpression());
          } while (this.match(TokenType.COMMA));
        }

        this.consume(TokenType.RPAREN);

        return {
          type: 'CallExpression',
          callee: {
            type: 'Identifier',
            name: `${nameToken.value}.${methodToken.value}`,
          },
          arguments: args,
        };
      }

      return {
        type: 'Identifier',
        name: nameToken.value,
      };
    }

    throw new Error(`Unexpected token: ${this.peek().type}`);
  }

  private parseAnnotation(): AST.Annotation {
    // Consume the @ token
    const atToken = this.advance();

    // The annotation name should be in the AT token's value after @
    // But our lexer includes the @ in the value, so we need to parse it differently
    let name = '';

    if (atToken.value.startsWith('@')) {
      name = atToken.value.substring(1);
    } else {
      name = this.consume(TokenType.IDENTIFIER).value;
    }

    const args: Record<string, any> = {};

    if (this.match(TokenType.LPAREN)) {
      // Parse annotation arguments (simplified - consume until RPAREN)
      if (!this.check(TokenType.RPAREN)) {
        while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
          this.advance();
        }
      }
      this.consume(TokenType.RPAREN);
    }

    return {
      name,
      args,
    };
  }

  // Utility methods
  private match(...types: TokenType[]): boolean {
    for (const type of types) {
      if (this.check(type)) {
        this.advance();
        return true;
      }
    }
    return false;
  }

  private check(type: TokenType): boolean {
    if (this.isAtEnd()) return false;
    return this.peek().type === type;
  }

  private advance(): Token {
    if (!this.isAtEnd()) this.current++;
    return this.previous();
  }

  private isAtEnd(): boolean {
    return this.peek().type === TokenType.EOF;
  }

  private peek(): Token {
    return this.tokens[this.current];
  }

  private peekNext(): Token | null {
    if (this.current + 1 >= this.tokens.length) return null;
    return this.tokens[this.current + 1];
  }

  private previous(): Token {
    return this.tokens[this.current - 1];
  }

  private consume(type: TokenType): Token {
    if (this.check(type)) return this.advance();

    throw new Error(
      `Expected ${type} but got ${this.peek().type} at line ${this.peek().line}`
    );
  }
}

class TypeScriptGenerator {
  private sourceMap: SourceMapGenerator;
  private generatedLine = 1;
  private generatedColumn = 0;
  private indent = 0;

  constructor(private sourceFileName: string) {
    this.sourceMap = new SourceMapGenerator({
      file: sourceFileName.replace('.agentic', '.ts'),
    });
  }

  generate(ast: AST.ASTNode[]): string {
    let code = '';

    // Add runtime imports
    code += this.generateRuntimeImports();

    // Generate each statement
    for (const node of ast) {
      code += this.generateNode(node);
      code += '\n\n';
      this.generatedLine += 2;
    }

    return code;
  }

  private generateRuntimeImports(): string {
    return `// Auto-generated from ${this.sourceFileName}
import { AgenticRuntime, Result, Ok, Err } from './runtime';

`;
  }

  private generateNode(node: AST.ASTNode): string {
    switch (node.type) {
      case 'FunctionDeclaration':
        return this.generateFunctionDeclaration(node);
      case 'VariableDeclaration':
        return this.generateVariableDeclaration(node);
      case 'ReturnStatement':
        return this.generateReturnStatement(node);
      case 'IfStatement':
        return this.generateIfStatement(node);
      case 'BlockStatement':
        return this.generateBlockStatement(node);
      case 'BinaryExpression':
        return this.generateBinaryExpression(node);
      case 'CallExpression':
        return this.generateCallExpression(node);
      case 'Identifier':
        return (node as AST.Identifier).name;
      case 'Literal':
        return this.generateLiteral(node);
      default:
        return `/* Unsupported node: ${node.type} */`;
    }
  }

  private generateFunctionDeclaration(node: AST.FunctionDeclaration): string {
    let code = '';

    // Generate annotations as decorators/comments
    for (const annotation of node.annotations) {
      code += `// @${annotation.name}\n`;
    }

    // Function signature
    code += `function ${node.name}(`;

    // Parameters
    const params = node.params.map(p => {
      const type = p.typeAnnotation ? this.generateTypeAnnotation(p.typeAnnotation) : 'any';
      return `${p.name}: ${type}`;
    });
    code += params.join(', ');

    code += ')';

    // Return type
    if (node.returnType) {
      code += `: ${this.generateTypeAnnotation(node.returnType)}`;
    }

    code += ' ';

    // Body
    code += this.generateBlockStatement(node.body);

    return code;
  }

  private generateTypeAnnotation(type: AST.TypeAnnotation): string {
    if (type.kind === 'primitive' || type.kind === 'custom') {
      return type.value as string;
    }

    if (type.kind === 'union' && Array.isArray(type.value)) {
      return type.value.map(t => this.generateTypeAnnotation(t)).join(' | ');
    }

    if (type.kind === 'result' && Array.isArray(type.value)) {
      const [okType, errType] = type.value;
      return `Result<${this.generateTypeAnnotation(okType)}, ${this.generateTypeAnnotation(errType)}>`;
    }

    return 'any';
  }

  private generateVariableDeclaration(node: AST.VariableDeclaration): string {
    const keyword = 'const'; // Default to const for safety
    let code = `${this.indentation()}${keyword} ${node.name}`;

    if (node.typeAnnotation) {
      code += `: ${this.generateTypeAnnotation(node.typeAnnotation)}`;
    }

    if (node.initializer) {
      code += ` = ${this.generateNode(node.initializer)}`;
    }

    code += ';';
    return code;
  }

  private generateReturnStatement(node: AST.ReturnStatement): string {
    let code = `${this.indentation()}return`;

    if (node.argument) {
      code += ` ${this.generateNode(node.argument)}`;
    }

    code += ';';
    return code;
  }

  private generateIfStatement(node: AST.IfStatement): string {
    let code = `${this.indentation()}if (${this.generateNode(node.condition)}) `;

    code += this.generateBlockStatement(node.consequent);

    if (node.alternate) {
      code += ' else ';
      if (node.alternate.type === 'IfStatement') {
        code += this.generateIfStatement(node.alternate).trim();
      } else {
        code += this.generateBlockStatement(node.alternate);
      }
    }

    return code;
  }

  private generateBlockStatement(node: AST.BlockStatement): string {
    let code = '{\n';
    this.indent++;

    for (const stmt of node.body) {
      code += this.generateNode(stmt);
      if (stmt.type !== 'IfStatement' && stmt.type !== 'BlockStatement') {
        if (!code.trim().endsWith(';')) {
          code += ';';
        }
      }
      code += '\n';
    }

    this.indent--;
    code += this.indentation() + '}';

    return code;
  }

  private generateBinaryExpression(node: AST.BinaryExpression): string {
    const left = this.generateNode(node.left);
    const right = this.generateNode(node.right);

    // Convert Agentic operators to TypeScript
    const operator = node.operator;

    return `${left} ${operator} ${right}`;
  }

  private generateCallExpression(node: AST.CallExpression): string {
    const callee = this.generateNode(node.callee);
    const args = node.arguments.map(arg => this.generateNode(arg)).join(', ');

    return `${callee}(${args})`;
  }

  private generateLiteral(node: AST.Literal): string {
    if (typeof node.value === 'string') {
      return `"${node.value}"`;
    }
    if (node.value === null) {
      return 'null';
    }
    return String(node.value);
  }

  private indentation(): string {
    return '  '.repeat(this.indent);
  }

  getSourceMap(): string {
    return JSON.stringify(this.sourceMap.toJSON());
  }

  getCodeWithInlineSourceMap(code: string): string {
    const map = Buffer.from(this.getSourceMap()).toString('base64');
    return `${code}\n//# sourceMappingURL=data:application/json;base64,${map}`;
  }
}

function add(a: number, b: number): number {
  return a;
}

function Ok<T>(value: T): Result<T, never> {
  return { ok: true, value };
}

function Err<E>(error: E): Result<never, E> {
  return { ok: false, error };
}

class AgenticRuntime {
  static confidence = {
    register: (name: string, level: number, reason?: string) => {
      if (level < 0.80) {
        console.warn(`⚠️  Low confidence (${level}) in ${name}`);
      }
    }
  };
